### Self-Referential Structures in C

A **self-referential structure** is a structure that includes one or more pointer members that point to an instance of the *same* structure type.

#### Why Self-Referential Structures are Essential:
- In standard C, a structure **cannot** contain a direct member of its own type (e.g., `struct Node next;`) because the compiler would not know its memory size (infinite recursion).
- However, a structure **can** contain a *pointer* to its own type (e.g., `struct Node *next;`), because the size of a pointer is fixed and known at compile-time (typically 4 or 8 bytes).
- This capability provides the fundamental building block for dynamic data structures (Linked Lists, Binary Trees, Graphs, and Hash Tables) where each node links to successor/child nodes.

#### Code Example: Implementing a Basic Linked List

```c
#include <stdio.h>
#include <stdlib.h>

// Definition of self-referential structure
struct Node {
    int data;
    struct Node* next; // Pointer to another node of type struct Node
};

int main() {
    // Dynamically allocate 3 nodes on Heap
    struct Node* head = (struct Node*)malloc(sizeof(struct Node));
    struct Node* second = (struct Node*)malloc(sizeof(struct Node));
    struct Node* third = (struct Node*)malloc(sizeof(struct Node));

    // Assign data and link them
    head->data = 10;
    head->next = second;

    second->data = 20;
    second->next = third;

    third->data = 30;
    third->next = NULL; // Marks end of the list

    // Traversal using the self-referential link
    struct Node* ptr = head;
    printf("Linked List Elements: ");
    while (ptr != NULL) {
        printf("%d -> ", ptr->data);
        ptr = ptr->next;
    }
    printf("NULL\n");

    // Free memory
    free(head); free(second); free(third);
    return 0;
}
```

### Customer Support Ticket System (Queue via Singly Linked List)

In a support ticket system, tickets operate on a **First-In, First-Out (FIFO)** basis: new tickets arrive at the end (rear), and the oldest ticket is processed and removed from the beginning (front).

#### A) Pseudocode to Insert New Ticket at End:

```text
Structure Ticket:
    id: Integer
    next: Pointer to Ticket
End Structure

Function InsertTicketAtEnd(Head, ticketId) -> Pointer to Ticket:
    newTicket = Allocate Ticket
    newTicket.id = ticketId
    newTicket.next = NULL

    If Head == NULL then
        Return newTicket
    End If

    curr = Head
    While curr.next != NULL do
        curr = curr.next
    End While
    curr.next = newTicket

    Return Head
End Function

```
*Time Complexity:* $O(n)$ with single pointer ($O(1)$ if rear pointer is maintained).

#### B) Pseudocode to Remove at the Beginning (Oldest Ticket):

```text
Function RemoveOldestTicket(Head, removedIdRef) -> Pointer to Ticket:
    If Head == NULL then
        Print "No tickets in system (Queue Underflow)"
        Return NULL
    End If

    oldestTicket = Head
    removedIdRef = oldestTicket.id
    Head = Head.next
    Free(oldestTicket)

    Print "Ticket processed and removed: ", removedIdRef
    Return Head
End Function

```
*Time Complexity:* $O(1)$.

#### C Implementation Snippet:

```c
struct Ticket {
    int id;
    struct Ticket* next;
};

struct Ticket* addTicket(struct Ticket* head, int id) {
    struct Ticket* newT = (struct Ticket*)malloc(sizeof(struct Ticket));
    newT->id = id;
    newT->next = NULL;
    if (head == NULL) return newT;
    struct Ticket* temp = head;
    while (temp->next != NULL) temp = temp->next;
    temp->next = newT;
    return head;
}

struct Ticket* processOldest(struct Ticket* head) {
    if (head == NULL) {
        printf("Ticket queue is empty.\n");
        return NULL;
    }
    struct Ticket* temp = head;
    printf("Processing ticket ID: %d\n", temp->id);
    head = head->next;
    free(temp);
    return head;
}
```

### Polynomial Linked List Implementation

For polynomial $P(x) = 6x^3 + 9x^2 + 7x + 1$, each node stores `(coeff, power, next)`.

```c
#include <stdio.h>
#include <stdlib.h>

struct PolyNode {
    int coeff;
    int power;
    struct PolyNode* next;
};

// A) Insert Term sorted by exponents (descending order)
struct PolyNode* insertTerm(struct PolyNode* head, int c, int p) {
    struct PolyNode* newNode = (struct PolyNode*)malloc(sizeof(struct PolyNode));
    newNode->coeff = c;
    newNode->power = p;
    newNode->next = NULL;

    // Case 1: Empty list or higher exponent than head
    if (head == NULL || p > head->power) {
        newNode->next = head;
        return newNode;
    }

    // Case 2: Exponent equals head power (merge coefficients)
    if (head->power == p) {
        head->coeff += c;
        free(newNode);
        return head;
    }

    // Case 3: Insert in intermediate or tail position
    struct PolyNode* curr = head;
    while (curr->next != NULL && curr->next->power > p) {
        curr = curr->next;
    }

    if (curr->next != NULL && curr->next->power == p) {
        curr->next->coeff += c; // Merge matching term
        free(newNode);
    } else {
        newNode->next = curr->next;
        curr->next = newNode;
    }
    return head;
}

// B) Display Polynomial
void displayPolynomial(struct PolyNode* head) {
    if (head == NULL) {
        printf("0\n");
        return;
    }
    struct PolyNode* curr = head;
    while (curr != NULL) {
        if (curr->power == 0) {
            printf("%d", curr->coeff);
        } else if (curr->power == 1) {
            printf("%dx", curr->coeff);
        } else {
            printf("%dx^%d", curr->coeff, curr->power);
        }

        if (curr->next != NULL && curr->next->coeff >= 0) {
            printf(" + ");
        } else if (curr->next != NULL) {
            printf(" ");
        }
        curr = curr->next;
    }
    printf("\n");
}

int main() {
    struct PolyNode* poly = NULL;
    // Inserting terms for: 6x^3 + 9x^2 + 7x + 1
    poly = insertTerm(poly, 7, 1); // 7x
    poly = insertTerm(poly, 1, 0); // 1
    poly = insertTerm(poly, 6, 3); // 6x^3
    poly = insertTerm(poly, 9, 2); // 9x^2

    printf("Polynomial representation:\n");
    displayPolynomial(poly);
    return 0;
}

```

**Output:**

```text
Polynomial representation:
6x^3 + 9x^2 + 7x + 1
```

### Employee Management System Using Dynamic Memory Allocation

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Employee {
    int empId;
    char name[50];
    char department[50];
    float salary;
};

struct Employee* employees = NULL;
int empCount = 0;
int capacity = 0;

// A) Add a new employee
void addEmployee(int id, const char* name, const char* dept, float sal) {
    if (empCount >= capacity) {
        capacity = (capacity == 0) ? 2 : capacity * 2;
        employees = (struct Employee*)realloc(employees, capacity * sizeof(struct Employee));
        if (employees == NULL) { printf("Memory allocation error!\n"); exit(1); }
    }
    employees[empCount].empId = id;
    strcpy(employees[empCount].name, name);
    strcpy(employees[empCount].department, dept);
    employees[empCount].salary = sal;
    empCount++;
    printf("Employee %s (ID: %d) added successfully.\n", name, id);
}

// B) Update employee's details
void updateEmployee(int id, const char* newDept, float newSal) {
    for (int i = 0; i < empCount; i++) {
        if (employees[i].empId == id) {
            strcpy(employees[i].department, newDept);
            employees[i].salary = newSal;
            printf("Employee ID %d updated successfully.\n", id);
            return;
        }
    }
    printf("Employee with ID %d not found!\n", id);
}

// C) Search for an employee by ID
void searchEmployee(int id) {
    for (int i = 0; i < empCount; i++) {
        if (employees[i].empId == id) {
            printf("\n--- Employee Found ---\n");
            printf("ID         : %d\n", employees[i].empId);
            printf("Name       : %s\n", employees[i].name);
            printf("Department : %s\n", employees[i].department);
            printf("Salary     : $%.2f\n", employees[i].salary);
            return;
        }
    }
    printf("Employee ID %d not found!\n", id);
}

// D) Display all employees
void displayAll() {
    if (empCount == 0) { printf("No employee records available.\n"); return; }
    printf("\n=================== Company Employee Directory ===================\n");
    printf("%-8s %-20s %-18s %-12s\n", "ID", "Name", "Department", "Salary");
    printf("------------------------------------------------------------------\n");
    for (int i = 0; i < empCount; i++) {
        printf("%-8d %-20s %-18s $%-11.2f\n", 
               employees[i].empId, employees[i].name, employees[i].department, employees[i].salary);
    }
    printf("==================================================================\n");
}

int main() {
    addEmployee(101, "Alice Smith", "Engineering", 85000.0);
    addEmployee(102, "Bob Jones", "Marketing", 62000.0);
    addEmployee(103, "Charlie Brown", "HR", 58000.0);

    displayAll();
    updateEmployee(102, "Product Management", 72000.0);
    searchEmployee(102);

    free(employees);
    return 0;
}
```

### Transpose of Dynamically Allocated 2D Matrix in C

```c
#include <stdio.h>
#include <stdlib.h>

// Function to transpose dynamically allocated matrix
int** transposeMatrix(int **mat, int rows, int cols) {
    // Transposed matrix has dimensions: cols x rows
    int **trans = (int **)malloc(cols * sizeof(int *));
    if (trans == NULL) return NULL;

    for (int i = 0; i < cols; i++) {
        trans[i] = (int *)malloc(rows * sizeof(int));
        if (trans[i] == NULL) return NULL;
    }

    // Perform transpose: trans[j][i] = mat[i][j]
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            trans[j][i] = mat[i][j];
        }
    }

    return trans;
}

void printMatrix(int **mat, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%4d ", mat[i][j]);
        }
        printf("\n");
    }
}

void freeMatrix(int **mat, int rows) {
    for (int i = 0; i < rows; i++) free(mat[i]);
    free(mat);
}

int main() {
    int r = 2, c = 3;

    // Allocate original 2x3 matrix
    int **matrix = (int **)malloc(r * sizeof(int *));
    for (int i = 0; i < r; i++) matrix[i] = (int *)malloc(c * sizeof(int));

    // Sample values: [[1, 2, 3], [4, 5, 6]]
    matrix[0][0] = 1; matrix[0][1] = 2; matrix[0][2] = 3;
    matrix[1][0] = 4; matrix[1][1] = 5; matrix[1][2] = 6;

    printf("Original Matrix (%dx%d):\n", r, c);
    printMatrix(matrix, r, c);

    // Transpose matrix
    int **transposed = transposeMatrix(matrix, r, c);

    printf("\nTransposed Matrix (%dx%d):\n", c, r);
    printMatrix(transposed, c, r);

    // Clean up dynamic memory
    freeMatrix(matrix, r);
    freeMatrix(transposed, c);

    return 0;
}

```

**Output:**

```text
Original Matrix (2x3):
   1    2    3 
   4    5    6 

Transposed Matrix (3x2):
   1    4 
   2    5 
   3    6
```

### Array-Based Customer Order Management System

#### 1. Data Structure Design:
We declare a fixed-size contiguous array of `struct Order` with tracking integer `totalOrders`.

```c
#define MAX_ORDERS 100

struct Order {
    int orderId;
    char customerName[50];
    float orderAmount;
};

struct Order orders[MAX_ORDERS];
int totalOrders = 0;

```

#### 2. Operations & Explanations:

**A. Insert at Specified Position ($pos$):**
- **Validation:** Check that array is not full (`totalOrders < MAX_ORDERS`) and $0 \le pos \le totalOrders$.
- **Shift Right:** Starting from the last order at `totalOrders - 1` down to `pos`, shift each record one position to the right (`orders[i+1] = orders[i]`).
- **Insert & Increment:** Store the new order at `orders[pos]` and increment `totalOrders`.
- *Complexity:* $O(n)$ in the worst/average case due to shifting.

**B. Remove by Order ID (`targetId`):**
- **Search:** Linearly scan the array to find the index $k$ where `orders[k].orderId == targetId`.
- **Shift Left:** Once found, overwrite the deleted slot by shifting elements from index $k+1$ up to `totalOrders - 1` one position left (`orders[i] = orders[i+1]`).
- **Decrement:** `totalOrders--`.
- *Complexity:* $O(n)$ time.

**C. Display All Orders:**
- Iterate from index $0$ to `totalOrders - 1` and print details.
- *Complexity:* $O(n)$ time.

#### 3. C Implementation:

```c
#include <stdio.h>
#include <string.h>

#define MAX 100

struct Order {
    int orderId;
    char name[50];
    float amount;
};

struct Order list[MAX];
int size = 0;

void insertAtPosition(int pos, int id, const char* name, float amt) {
    if (size >= MAX) { printf("Array overflow!\n"); return; }
    if (pos < 0 || pos > size) { printf("Invalid insertion index %d!\n", pos); return; }

    for (int i = size - 1; i >= pos; i--) {
        list[i + 1] = list[i]; // Shift right
    }
    list[pos].orderId = id;
    strcpy(list[pos].name, name);
    list[pos].amount = amt;
    size++;
    printf("Order %d inserted at position %d.\n", id, pos);
}

void removeByOrderId(int id) {
    int idx = -1;
    for (int i = 0; i < size; i++) {
        if (list[i].orderId == id) { idx = i; break; }
    }
    if (idx == -1) { printf("Order ID %d not found!\n", id); return; }

    for (int i = idx; i < size - 1; i++) {
        list[i] = list[i + 1]; // Shift left
    }
    size--;
    printf("Order ID %d removed successfully.\n", id);
}

void displayOrders() {
    printf("\n--- Current Active Orders (%d orders) ---\n", size);
    printf("%-6s %-10s %-20s %-10s\n", "Index", "Order ID", "Customer Name", "Amount");
    for (int i = 0; i < size; i++) {
        printf("[%-4d] %-10d %-20s $%-9.2f\n", i, list[i].orderId, list[i].name, list[i].amount);
    }
}
```

### Photo Album Manager Application using Singly Linked List

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Photo {
    int id;
    char title[50];
    struct Photo* next;
};

// 1. Insert photo at specific position (1-based index)
struct Photo* insertAtPosition(struct Photo* head, int pos, int id, const char* title) {
    struct Photo* newP = (struct Photo*)malloc(sizeof(struct Photo));
    newP->id = id;
    strcpy(newP->title, title);
    newP->next = NULL;

    if (pos == 1 || head == NULL) {
        newP->next = head;
        return newP;
    }

    struct Photo* curr = head;
    for (int i = 1; i < pos - 1 && curr->next != NULL; i++) {
        curr = curr->next;
    }
    newP->next = curr->next;
    curr->next = newP;
    return head;
}

// 2. Remove photo by ID
struct Photo* removePhotoById(struct Photo* head, int targetId) {
    if (head == NULL) return NULL;
    if (head->id == targetId) {
        struct Photo* temp = head;
        head = head->next;
        free(temp);
        printf("Photo ID %d removed.\n", targetId);
        return head;
    }

    struct Photo* curr = head;
    while (curr->next != NULL && curr->next->id != targetId) {
        curr = curr->next;
    }
    if (curr->next != NULL) {
        struct Photo* temp = curr->next;
        curr->next = temp->next;
        free(temp);
        printf("Photo ID %d removed.\n", targetId);
    } else {
        printf("Photo ID %d not found.\n", targetId);
    }
    return head;
}

// 3. Move photo to a different position
struct Photo* movePhoto(struct Photo* head, int photoId, int newPos) {
    if (head == NULL) return NULL;

    // Step A: Extract node with photoId without freeing it
    struct Photo *target = NULL, *prev = NULL, *curr = head;
    if (head->id == photoId) {
        target = head;
        head = head->next;
    } else {
        while (curr->next != NULL && curr->next->id != photoId) {
            curr = curr->next;
        }
        if (curr->next != NULL) {
            target = curr->next;
            curr->next = target->next;
        }
    }

    if (target == NULL) {
        printf("Photo ID %d not found to move.\n", photoId);
        return head;
    }

    // Step B: Re-insert target node at newPos
    target->next = NULL;
    if (newPos == 1 || head == NULL) {
        target->next = head;
        return target;
    }

    curr = head;
    for (int i = 1; i < newPos - 1 && curr->next != NULL; i++) {
        curr = curr->next;
    }
    target->next = curr->next;
    curr->next = target;
    printf("Photo ID %d moved to position %d.\n", photoId, newPos);
    return head;
}

// 4. Display all photos
void displayAlbum(struct Photo* head) {
    printf("\n--- Photo Album Gallery ---\n");
    int pos = 1;
    struct Photo* curr = head;
    while (curr != NULL) {
        printf("[%d] Photo ID: %-5d | Title: %s\n", pos++, curr->id, curr->title);
        curr = curr->next;
    }
}

int main() {
    struct Photo* album = NULL;
    album = insertAtPosition(album, 1, 101, "Beach Sunset");
    album = insertAtPosition(album, 2, 102, "Mountain Hike");
    album = insertAtPosition(album, 3, 103, "Family Dinner");
    album = insertAtPosition(album, 2, 104, "City Skyline"); // Insert at pos 2
    displayAlbum(album);

    album = movePhoto(album, 103, 1); // Move Family Dinner to 1st position
    displayAlbum(album);

    album = removePhotoById(album, 102);
    displayAlbum(album);

    return 0;
}
```
